export function eligible(r,s,meal){if(!r||!r.meal.includes(meal)||r.time==null||r.time>s.maxTime)return false;if(s.diet==='Vegan'&&r.diet!=='Vegan')return false;if(['Vegetarisch','Pescetarisch'].includes(s.diet)&&!['Vegan','Vegetarisch',...(s.diet==='Pescetarisch'?['Pescetarisch']:[])].includes(r.diet))return false;const excluded=[...s.allergens,...(s.glutenfree?['Gluten']:[]),...(s.lactosefree?['Milch']:[])];if(excluded.length&&!r.verified)return false;if(r.ingredients.some(i=>!foods[i.food] ? excluded.length>0 : foods[i.food].allergens.some(a=>excluded.includes(a))))return false;const bad=s.excludes.toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);if(r.ingredients.some(i=>bad.some(b=>(foods[i.food]?.name||i.food).toLowerCase().includes(b))))return false;if(s.goals.includes('Proteinreich')&&(!r.protein||r.protein<s.minProtein))return false;if(s.goals.includes('Low Carb')&&(r.carbs==null||r.carbs>s.maxCarbs))return false;if(s.goals.includes('Kalorienarm')&&(r.kcal==null||r.kcal>s.maxKcal))return false;if(s.goals.includes('Kalorienreich')&&(r.kcal==null||r.kcal<s.minKcal))return false;return true;}
export function shopping(plan,recipes,pantry={},prices={}){const map={};for(const p of Object.values(plan)){if(p.leftover||p.cooked)continue;const r=recipes.find(r=>r.id===p.recipe);if(!r)continue;for(const i of r.ingredients){const f=foods[i.food]||{name:i.food,unit:i.unit||'g',pack:0,price:0,group:'Eigene Zutaten'};const key=i.food+'|'+f.unit;const row=map[key]??={key,food:i.food,...f,qty:0,dishes:[]};row.qty+=i.qty*p.portions/r.servings;if(!row.dishes.includes(r.title))row.dishes.push(r.title);}}return Object.values(map).map(x=>{const need=Math.max(0,x.qty-(pantry[x.food]||0));const price=prices[x.food]??x.price;return {...x,need,packs:x.pack?Math.ceil(need/x.pack):null,cost:x.pack?Math.ceil(need/x.pack)*price:0,used:x.pack?x.qty/x.pack*price:0,price};});}
export function totals(rows){return {buy:rows.reduce((s,r)=>s+r.cost,0),used:rows.reduce((s,r)=>s+r.used,0),unknown:rows.some(r=>r.packs===null)};}
export function planAuto(state){const result={};const old=state.plans[state.week]||{};for(const [key,v]of Object.entries(old))if(v.locked){const [d,m]=key.split('-');const r=state.recipes.find(r=>r.id===v.recipe);if(state.settings.days.includes(+d)&&state.settings.meals.includes(m)&&r&&eligible(r,state.settings,m))result[key]=v;}
let misses=[];for(const d of state.settings.days)for(const m of state.settings.meals){const key=d+'-'+m;if(result[key])continue;const options=state.recipes.filter(r=>eligible(r,state.settings,m));if(!options.length){misses.push(days[d]+' '+m);continue;}const scored=options.map(r=>{const p={...result,[key]:{recipe:r.id,portions:state.settings.persons}};const cost=totals(shopping(p,state.recipes,state.pantry,state.prices)).buy;const repeats=Object.values(result).filter(p=>p.recipe===r.id).length;return {r,score:cost+repeats*2-(state.settings.preferFav&&r.favorite?1:0)};}).sort((a,b)=>a.score-b.score);result[key]={recipe:scored[0].r.id,portions:state.settings.persons};}return {plan:result,misses};}
export function parseText(text){const lines=text.split('\n').map(x=>x.trim()).filter(Boolean);let section='ingredients',ingredients=[],steps=[];for(const line of lines.slice(1)){if(/^(zutaten|ingredients)\s*:?$/i.test(line)){section='ingredients';continue;}if(/^(zubereitung|schritte|anleitung|instructions)\s*:?$/i.test(line)){section='steps';continue;}if(section==='steps'){steps.push(line.replace(/^\d+[.)]\s*/,''));continue;}const match=line.match(/^[-•]?\s*(\d+(?:[.,]\d+)?)\s*(kg|g|ml|l|Stück|EL|TL)?\s+(.+)$/i);if(match){let qty=+match[1].replace(',','.');let unit=match[2]||'Stück';if(unit==='kg'){qty*=1000;unit='g';}if(unit==='l'){qty*=1000;unit='ml';}const known=Object.entries(foods).find(([,f])=>f.name.toLowerCase()===match[3].toLowerCase()&&f.unit===unit);ingredients.push({food:known?.[0]||match[3],qty,unit});}else ingredients.push({food:line,qty:0,unit:'?',unclear:true});}return {id:'r'+Date.now(),title:lines[0]||'Neues Rezept',servings:2,ingredients,steps,time:null,prep:null,kcal:null,protein:null,carbs:null,fat:null,diet:'Ungeprüft',meal:['Mittagessen','Abendessen'],tags:['Importiert'],verified:false,source:'Textimport · Angaben prüfen'};}

// A single meal, isolated from the weekly plan and its budget.
export function quickSuggestions(state,options){
 const {budget,portions,maxTime,meal,highProtein,minProtein,usePantry}=options;
 if(!Number.isFinite(budget)||budget<0||!Number.isInteger(portions)||portions<1||portions>30||!Number.isFinite(maxTime)||maxTime<1||!Number.isFinite(minProtein)||minProtein<0)throw new Error('Bitte gültiges Budget, Zeitlimit und 1–30 Portionen eingeben.');
 const settings={...state.settings,maxTime,goals:[...new Set([...state.settings.goals,...(highProtein?['Proteinreich']:[])])],minProtein:Math.max(highProtein?minProtein:0,state.settings.goals.includes('Proteinreich')?state.settings.minProtein:0)};
 const candidates=state.recipes.filter(r=>eligible(r,settings,meal)).map(r=>{const rows=shopping({quick:{recipe:r.id,portions}},state.recipes,usePantry?state.pantry:{},state.prices);const total=totals(rows);return {recipe:r,rows,...total,portions};}).filter(x=>!x.unknown).sort((a,b)=>a.buy-b.buy||a.recipe.time-b.recipe.time);
 return {matches:candidates.filter(x=>Math.round(x.buy*100)<=Math.round(budget*100)),alternatives:candidates.filter(x=>Math.round(x.buy*100)>Math.round(budget*100)).slice(0,3)};
}

